def parse_nested_parens(paren_string: str) -> List[int]:
    groups = paren_string.split()
    results = []
    for group in groups:
        max_depth = 0
        curr_depth = 0
        for char in group:
            if char == '(': 
                curr_depth += 1
                max_depth = max(max_depth, curr_depth)
            elif char == ')':
                curr_depth -= 1
                if curr_depth < 0:
                    raise ValueError("Unbalanced parentheses in the input string")
        if curr_depth != 0:
            raise ValueError("Unbalanced parentheses in the input string")
        results.append(max_depth)
    return results
